{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2171-05-17 13:15:00",
      "speaker": "Doctor",
      "text": "Hi, I'm Dr. Lee. You're in the hospital because EMS found you unresponsive in your car. Do you remember what happened?"
    },
    {
      "turn_number": 2,
      "time": "2171-05-17 13:16:00",
      "speaker": "Patient",
      "text": "I... I took some of my meds. Clonidine, Haldol, and Zyprexa. I just felt so overwhelmed."
    },
    {
      "turn_number": 3,
      "time": "2171-05-17 13:17:00",
      "speaker": "Doctor",
      "text": "Thank you for telling me. We’re here to help. You were very sleepy when you arrived—your GCS was 8—and we had to intubate you to protect your airway."
    },
    {
      "turn_number": 4,
      "time": "2171-05-17 13:18:00",
      "speaker": "Patient",
      "text": "I don’t remember that. Was I in danger?"
    },
    {
      "turn_number": 5,
      "time": "2171-05-17 13:19:00",
      "speaker": "Doctor",
      "text": "Yes, your breathing slowed down, and we needed to make sure you could get enough oxygen. The tube has been adjusted and you’re breathing with the machine now."
    },
    {
      "turn_number": 6,
      "time": "2171-05-17 13:20:00",
      "speaker": "Patient",
      "text": "I’m scared. Did I hurt my brain?"
    },
    {
      "turn_number": 7,
      "time": "2171-05-17 13:21:00",
      "speaker": "Doctor",
      "text": "We did a CT scan of your head, and there’s no bleeding or stroke. Your brain looks normal. That’s a good sign."
    },
    {
      "turn_number": 8,
      "time": "2171-05-17 13:22:00",
      "speaker": "Patient",
      "text": "What about my heart? I’ve had issues before."
    },
    {
      "turn_number": 9,
      "time": "2171-05-17 13:23:00",
      "speaker": "Doctor",
      "text": "We noticed your heart rate was slow—56—and your QT interval was prolonged, over 500 milliseconds. That can happen with too much Haldol or Zyprexa, especially with clonidine."
    },
    {
      "turn_number": 10,
      "time": "2171-05-17 13:24:00",
      "speaker": "Patient",
      "text": "Is that dangerous?"
    },
    {
      "turn_number": 11,
      "time": "2171-05-17 13:25:00",
      "speaker": "Doctor",
      "text": "It can be, but we’re monitoring you on telemetry. We stopped the QT-prolonging meds for now and corrected your electrolytes. Your rhythm is stable."
    },
    {
      "turn_number": 12,
      "time": "2171-05-17 13:26:00",
      "speaker": "Patient",
      "text": "I’ve been on lithium for years. Should I stop that too?"
    },
    {
      "turn_number": 13,
      "time": "2171-05-17 13:27:00",
      "speaker": "Doctor",
      "text": "The psychiatry team reviewed your case. They recommend continuing lithium, but we’ll restart it slowly and monitor your levels."
    },
    {
      "turn_number": 14,
      "time": "2171-05-17 13:28:00",
      "speaker": "Patient",
      "text": "Okay. I was doing better after my last psych stay, but then I got so tired."
    },
    {
      "turn_number": 15,
      "time": "2171-05-17 13:29:00",
      "speaker": "Doctor",
      "text": "Your family mentioned you were searching ‘olanzapine overdose’ earlier that day. Were you planning this?"
    },
    {
      "turn_number": 16,
      "time": "2171-05-17 13:30:00",
      "speaker": "Patient",
      "text": "I didn’t plan it exactly. I just felt numb and wanted it to stop."
    },
    {
      "turn_number": 17,
      "time": "2171-05-17 13:31:00",
      "speaker": "Doctor",
      "text": "I understand. We’re going to make sure you get the mental health support you need after this."
    },
    {
      "turn_number": 18,
      "time": "2171-05-17 15:00:00",
      "speaker": "Doctor",
      "text": "We did a chest X-ray after you were intubated. The tube was too far in, in your right main bronchus, so we pulled it back."
    },
    {
      "turn_number": 19,
      "time": "2171-05-17 15:01:00",
      "speaker": "Patient",
      "text": "Was that why I couldn’t breathe?"
    },
    {
      "turn_number": 20,
      "time": "2171-05-17 15:02:00",
      "speaker": "Doctor",
      "text": "It contributed. That caused part of your lung to collapse. Now the tube is in the right place, and your left lung is opening up."
    },
    {
      "turn_number": 21,
      "time": "2171-05-17 15:03:00",
      "speaker": "Patient",
      "text": "Good. I feel a little more air moving."
    },
    {
      "turn_number": 22,
      "time": "2171-05-17 18:30:00",
      "speaker": "Doctor",
      "text": "Your labs showed a mild metabolic acidosis with a lactate of 3.0. We gave fluids, and it’s improving."
    },
    {
      "turn_number": 23,
      "time": "2171-05-17 18:31:00",
      "speaker": "Patient",
      "text": "What does that mean?"
    },
    {
      "turn_number": 24,
      "time": "2171-05-17 18:32:00",
      "speaker": "Doctor",
      "text": "Your body was under stress from the overdose, and your tissues weren’t getting enough oxygen for a while. The fluids helped reverse that."
    },
    {
      "turn_number": 25,
      "time": "2171-05-17 18:33:00",
      "speaker": "Patient",
      "text": "I feel less foggy now."
    },
    {
      "turn_number": 26,
      "time": "2171-05-17 18:34:00",
      "speaker": "Doctor",
      "text": "That’s great. Your mental status is clearing, which we expected as the drugs wear off."
    },
    {
      "turn_number": 27,
      "time": "2171-05-18 07:00:00",
      "speaker": "Doctor",
      "text": "Another chest X-ray shows your lungs are stable. No pneumonia. Just a little atelectasis, which is common after being on a ventilator."
    },
    {
      "turn_number": 28,
      "time": "2171-05-18 07:01:00",
      "speaker": "Patient",
      "text": "Can I get off the breathing machine soon?"
    },
    {
      "turn_number": 29,
      "time": "2171-05-18 07:02:00",
      "speaker": "Doctor",
      "text": "We’re planning to try extubation today. You’re breathing well on your own with the support, and your strength is returning."
    },
    {
      "turn_number": 30,
      "time": "2171-05-18 10:15:00",
      "speaker": "Doctor",
      "text": "You did great. We removed the breathing tube about an hour ago, and you’re breathing on your own without trouble."
    },
    {
      "turn_number": 31,
      "time": "2171-05-18 10:16:00",
      "speaker": "Patient",
      "text": "I can talk again. That feels good."
    },
    {
      "turn_number": 32,
      "time": "2171-05-18 10:17:00",
      "speaker": "Doctor",
      "text": "Yes, and your voice is strong. We’ll keep monitoring you closely, but this is a big step forward."
    },
    {
      "turn_number": 33,
      "time": "2171-05-18 14:00:00",
      "speaker": "Patient",
      "text": "My arm where the IV is feels sore and red."
    },
    {
      "turn_number": 34,
      "time": "2171-05-18 14:01:00",
      "speaker": "Doctor",
      "text": "I see a small area of redness and tenderness. It looks like mild phlebitis. We’ll switch your IV and watch it."
    },
    {
      "turn_number": 35,
      "time": "2171-05-18 14:02:00",
      "speaker": "Patient",
      "text": "Could it get infected?"
    },
    {
      "turn_number": 36,
      "time": "2171-05-18 14:03:00",
      "speaker": "Doctor",
      "text": "It’s unlikely. We screened for MRSA and it was negative. If it worsens, we might give a short course of antibiotics, but for now, just observation."
    },
    {
      "turn_number": 37,
      "time": "2171-05-19 09:00:00",
      "speaker": "Doctor",
      "text": "Your QT interval has normalized. That’s excellent. We’ll keep you on telemetry a bit longer, but you’re improving."
    },
    {
      "turn_number": 38,
      "time": "2171-05-19 09:01:00",
      "speaker": "Patient",
      "text": "So my heart is okay now?"
    },
    {
      "turn_number": 39,
      "time": "2171-05-19 09:02:00",
      "speaker": "Doctor",
      "text": "Yes. The combination of the drugs and slow heart rate caused the issue, but now that you’re off them and hydrated, it’s resolved."
    },
    {
      "turn_number": 40,
      "time": "2171-05-19 13:00:00",
      "speaker": "Patient",
      "text": "I’ve been thinking. I don’t want to go back to how I was. Can I get more help?"
    },
    {
      "turn_number": 41,
      "time": "2171-05-19 13:01:00",
      "speaker": "Doctor",
      "text": "Absolutely. The psychiatry team recommends a longer stay at a psychiatric facility. You’ll be transferred there after medical clearance."
    },
    {
      "turn_number": 42,
      "time": "2171-05-19 13:02:00",
      "speaker": "Patient",
      "text": "I think that’s what I need."
    },
    {
      "turn_number": 43,
      "time": "2171-05-20 10:00:00",
      "speaker": "Doctor",
      "text": "Your stool test came back negative for C. difficile. So no need for antibiotics there."
    },
    {
      "turn_number": 44,
      "time": "2171-05-20 10:01:00",
      "speaker": "Patient",
      "text": "I’ve had diarrhea before with meds. Just wanted to make sure."
    },
    {
      "turn_number": 45,
      "time": "2171-05-20 10:02:00",
      "speaker": "Doctor",
      "text": "Good to check. But everything looks clear. Your labs are stable, and you’re eating and moving around well."
    },
    {
      "turn_number": 46,
      "time": "2171-05-21 14:00:00",
      "speaker": "Doctor",
      "text": "We’re finalizing your discharge plan. You’ll be transferred to a psychiatric facility tomorrow morning."
    },
    {
      "turn_number": 47,
      "time": "2171-05-21 14:01:00",
      "speaker": "Patient",
      "text": "Okay. What meds will I be on?"
    },
    {
      "turn_number": 48,
      "time": "2171-05-21 14:02:00",
      "speaker": "Doctor",
      "text": "Lithium 600 mg at bedtime, trazodone for sleep, and your albuterol for asthma as needed. We’re adding iron and stool softener too."
    },
    {
      "turn_number": 49,
      "time": "2171-05-21 14:03:00",
      "speaker": "Patient",
      "text": "No more Haldol or Zyprexa?"
    },
    {
      "turn_number": 50,
      "time": "2171-05-21 14:04:00",
      "speaker": "Doctor",
      "text": "Not right now. The psych team will decide if and when to restart, but carefully. Your safety comes first."
    },
    {
      "turn_number": 51,
      "time": "2171-05-21 16:00:00",
      "speaker": "Patient",
      "text": "I’m nervous about going back, but I know I need help."
    },
    {
      "turn_number": 52,
      "time": "2171-05-21 16:01:00",
      "speaker": "Doctor",
      "text": "It’s brave to face that. You’re medically stable, and the next step is getting the right psychiatric care."
    },
    {
      "turn_number": 53,
      "time": "2171-05-21 20:00:00",
      "speaker": "Doctor",
      "text": "Just checking in. You’ve done really well this week. Clear mind, strong heart, breathing on your own."
    },
    {
      "turn_number": 54,
      "time": "2171-05-21 20:01:00",
      "speaker": "Patient",
      "text": "Thank you. I feel like I have a second chance."
    },
    {
      "turn_number": 55,
      "time": "2171-05-21 20:02:00",
      "speaker": "Doctor",
      "text": "You do. And we’re making sure you get the support to use it."
    },
    {
      "turn_number": 56,
      "time": "2171-05-22 00:05:00",
      "speaker": "Doctor",
      "text": "It’s time to transfer you. You’re alert, walking, and medically cleared. The facility is expecting you."
    },
    {
      "turn_number": 57,
      "time": "2171-05-22 00:06:00",
      "speaker": "Patient",
      "text": "I’m ready. Thank you for not giving up on me."
    },
    {
      "turn_number": 58,
      "time": "2171-05-22 00:07:00",
      "speaker": "Doctor",
      "text": "We’re glad we could help. Take care, and keep working on your recovery."
    },
    {
      "turn_number": 59,
      "time": "2171-05-22 00:08:00",
      "speaker": "Patient",
      "text": "I will."
    },
    {
      "turn_number": 60,
      "time": "2171-05-22 00:09:00",
      "speaker": "Doctor",
      "text": "The transport team will take you shortly. You’ve come a long way in five days."
    },
    {
      "turn_number": 61,
      "time": "2171-05-22 00:10:00",
      "speaker": "Patient",
      "text": "I feel like a different person."
    },
    {
      "turn_number": 62,
      "time": "2171-05-22 00:11:00",
      "speaker": "Doctor",
      "text": "That’s the goal. Keep going."
    },
    {
      "turn_number": 63,
      "time": "2171-05-22 00:12:00",
      "speaker": "Patient",
      "text": "I will."
    },
    {
      "turn_number": 64,
      "time": "2171-05-22 00:13:00",
      "speaker": "Doctor",
      "text": "Take care. We’ll send your records to the facility."
    }
  ],
  "summary": {
    "admission_start": "2171-05-17 13:12:00",
    "admission_end": "2171-05-22 00:14:00",
    "summary_paragraph": "A female patient with bipolar disorder, asthma, and a history of multiple suicide attempts was admitted after being found unresponsive in her car following a drug overdose involving clonidine, haloperidol, and olanzapine. She presented with altered mental status, a GCS of 8, bradycardia, and prolonged QT interval. Intubation was performed for airway protection, and she was managed in the medical unit with fluid resuscitation, electrolyte repletion, and telemetry monitoring. The metabolic acidosis and QT prolongation resolved over the course of admission. She was successfully extubated on hospital day two and regained full mental clarity. A small area of phlebitis at an IV site was noted but did not progress. She was stabilized on lithium and other supportive medications, and psychiatric evaluation recommended transfer to a long-term psychiatric facility. She was discharged medically stable and alert, with plans for continued mental health treatment.",
    "problems": [
      "Poisoning by butyrophenone-based tranquilizers",
      "Bipolar I disorder, most recent episode (or current) depressed, unspecified",
      "Poisoning by benzodiazepine-based tranquilizers",
      "Poisoning by other antihypertensive agents",
      "Other alteration of consciousness",
      "Suicide and self-inflicted poisoning by tranquilizers and other psychotropic agents",
      "Long QT syndrome",
      "Phlebitis and thrombophlebitis of superficial veins of upper extremities",
      "Asthma, unspecified type, unspecified",
      "Esophageal reflux"
    ]
  }
}
